    data-rt-section-id="{{ section.id }}"
    data-rt-vat-rate="0.21"
    data-rt-price-includes-vat="true"
    data-rt-hide-base-unit-cents-lte="1"
    data-rt-money-format="{{ shop.money_format | escape }}"
    data-rt-locale="{{ request.locale.iso_code }}"
    data-rt-currency="{{ cart.currency.iso_code | default: shop.currency }}"
  >
