          {"id":{{ v.id }},"price":{{ v.price }}}{%- unless forloop.last -%},{%- endunless -%}
        {%- endfor -%}
      ]
    </script>
  </div>
{%- endif -%}

{%- comment -%}
  FENDER RFQ — Nederlands
  Zijaanzicht met eigen variant-dropdown.

  Variant titel formaat:
    DD-fender 042x027mm d-bore 027x013mm

  Uitgelezen maten:
    A = 42  -> Profielhoogte / HB, intern gebruikt
    B = 27  -> Breedte, niet zichtbaar / niet relevant in zijaanzicht
    C = 27  -> Kamerhoogte, alleen gebruikt voor stippellijnen
    D = 13  -> Kamerbreedte, alleen meegestuurd in samenvatting

  Invoer:
    L  = Lengte
    G  = afstand linkerkant tot hart eerste gat
    H  = hart-op-hart afstand
    Ø  = gatdiameter
    N  = aantal gaten
    HC = hart hoogte gaten vanaf onderzijde

  Berekend:
    GR = rechterafstand vanaf laatste gat-hart tot rechterzijde

  Contact form:
    Standaard Shopify /contact formulier.
    Afbeelding/SVG kan niet als echte bijlage worden meegestuurd zonder app/backend.
    Wel wordt een configuratie-URL meegestuurd.
{%- endcomment -%}

{%- assign v   = product.selected_or_first_available_variant -%}
{%- assign uid = 'fender-rfq-' | append: product.id -%}

<div id="{{ uid }}" class="frq">

  <div class="frq__preview">
    <div class="frq__card">
      <div class="frq__head">
        <div>
          <div class="frq__headTitle">Zijaanzicht (2D)</div>
          <div class="frq__headSub">Lengte, gaten, harthoogte en kamerindicatie</div>
        </div>
        <div class="frq__headMeta">Live voorbeeld</div>
      </div>

      <div class="frq__svgWrap">
        <svg class="frq__svg" viewBox="0 0 1200 430"
             preserveAspectRatio="xMidYMid meet" role="img" aria-label="Fenderblok zijaanzicht">

          <defs>
            <marker id="{{ uid }}-arr" viewBox="0 0 10 10" refX="5" refY="5"
                    markerWidth="5" markerHeight="5" orient="auto-start-reverse">
              <path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"/>
            </marker>
          </defs>

          <g class="f-shape" aria-hidden="true">
            <rect class="f-fill" x="0" y="0" width="0" height="0" rx="2"/>
            <rect class="f-outline" x="0" y="0" width="0" height="0" rx="2"/>

            <!-- kamerindicatie: 2 stippellijnen, volledige breedte -->
            <line class="f-hidden" data-d="C-top"/>
            <line class="f-hidden" data-d="C-bot"/>

            <g class="f-holes"></g>
          </g>

          <g class="f-dims" aria-hidden="true">
            <!-- L -->
            <line class="de" data-d="L-el"/>
            <line class="de" data-d="L-er"/>
            <line class="dl" data-d="L-line"
                  marker-start="url(#{{ uid }}-arr)"
                  marker-end="url(#{{ uid }}-arr)"/>
            <text class="dt" data-d="L-text" text-anchor="middle"></text>

            <!-- HB, intern uit variant -->
            <line class="de" data-d="HB-et"/>
            <line class="de" data-d="HB-eb"/>
            <line class="dl" data-d="HB-line"
                  marker-start="url(#{{ uid }}-arr)"
                  marker-end="url(#{{ uid }}-arr)"/>
            <text class="dt" data-d="HB-text" text-anchor="middle"></text>

            <!-- G links -->
            <line class="de" data-d="G-el"/>
            <line class="de" data-d="G-em"/>
            <line class="dl" data-d="G-line"
                  marker-start="url(#{{ uid }}-arr)"
                  marker-end="url(#{{ uid }}-arr)"/>
            <text class="dt" data-d="G-text" text-anchor="middle"></text>

            <!-- H hart-op-hart -->
            <line class="de" data-d="H-em"/>
            <line class="de" data-d="H-er"/>
            <line class="dl" data-d="H-line"
                  marker-start="url(#{{ uid }}-arr)"
                  marker-end="url(#{{ uid }}-arr)"/>
            <text class="dt" data-d="H-text" text-anchor="middle"></text>

            <!-- GR rechterafstand -->
            <line class="de" data-d="GR-el"/>
            <line class="de" data-d="GR-er"/>
            <line class="dl" data-d="GR-line"
                  marker-start="url(#{{ uid }}-arr)"
                  marker-end="url(#{{ uid }}-arr)"/>
            <text class="dt" data-d="GR-text" text-anchor="middle"></text>

            <!-- Ø -->
            <text class="dt f-dia-text" data-d="DIA-text" text-anchor="middle"></text>

            <!-- HC -->
            <line class="de" data-d="HC-et"/>
            <line class="de" data-d="HC-eb"/>
            <line class="dl" data-d="HC-line"
                  marker-start="url(#{{ uid }}-arr)"
                  marker-end="url(#{{ uid }}-arr)"/>
            <text class="dt" data-d="HC-text" text-anchor="start"></text>
          </g>

          <text class="f-warn" x="600" y="412" text-anchor="middle"></text>
        </svg>
      </div>
    </div>

    <div class="frq__svgWarn" id="{{ uid }}-svgwarn" aria-live="polite"></div>
  </div>

  <div class="frq__form">
    <h3 class="frq__title">2D Tool</h3>
    <div class="frq__sub" data-sub>Kies een variant en vul de maten in.</div>
    <div class="frq__success" data-success hidden></div>

    <form method="post" action="/contact" accept-charset="UTF-8" data-frq-form>
      <input type="hidden" name="form_type" value="contact">
      <input type="hidden" name="utf8" value="✓">

      <input type="hidden" name="contact[Product]" value="{{ product.title | escape }}">
      <input type="hidden" name="contact[Product URL]" value="{{ shop.url }}{{ product.url }}">
      <input type="hidden" name="contact[Variant]" id="{{ uid }}-variant-hidden" value="{{ v.title | escape }}">
      <input type="hidden" name="contact[SKU]" id="{{ uid }}-sku-hidden" value="{{ v.sku | escape }}">

      <!-- intern/meegestuurd, niet zichtbaar -->
      <input type="hidden" name="contact[Profielhoogte_HB_mm]" id="{{ uid }}-HB-hidden">
      <input type="hidden" name="contact[Profielbreedte_B_mm]" id="{{ uid }}-B-hidden">
      <input type="hidden" name="contact[Kamerhoogte_C_mm]" id="{{ uid }}-C-hidden">
      <input type="hidden" name="contact[Kamerbreedte_D_mm]" id="{{ uid }}-D-hidden">
      <input type="hidden" name="contact[Rechterafstand_GR_mm]" id="{{ uid }}-GR-hidden">

      <!-- Tracking -->
      <input type="hidden" name="contact[landing_url]" id="{{ uid }}-trk-land">
      <input type="hidden" name="contact[referrer]" id="{{ uid }}-trk-ref">
      <input type="hidden" name="contact[user_agent]" id="{{ uid }}-trk-ua">
      <input type="hidden" name="contact[utm_source]" id="{{ uid }}-trk-src">
      <input type="hidden" name="contact[utm_medium]" id="{{ uid }}-trk-med">
      <input type="hidden" name="contact[utm_campaign]" id="{{ uid }}-trk-camp">
      <input type="hidden" name="contact[utm_content]" id="{{ uid }}-trk-cont">
      <input type="hidden" name="contact[utm_term]" id="{{ uid }}-trk-term">
      <input type="hidden" name="contact[gclid]" id="{{ uid }}-trk-gclid">

      <input type="hidden" name="contact[Configuratie URL]" id="{{ uid }}-config-url">
      <input type="hidden" name="contact[Samenvatting]" id="{{ uid }}-summary">

      <script type="application/json" id="{{ uid }}-variant-data">
      [
        {% for variant in product.variants %}
          {
            "id": {{ variant.id | json }},
            "title": {{ variant.title | json }},
            "sku": {{ variant.sku | json }}
          }{% unless forloop.last %},{% endunless %}
        {% endfor %}
      ]
      </script>

      <div class="frq__section-label">Profiel / variant</div>

      <div class="frq__row frq__row--2">
        <div>
          <label class="frq__label" for="{{ uid }}-variant-select">Kies variant *</label>
          <select class="frq__input" id="{{ uid }}-variant-select" required>
            {% for variant in product.variants %}
              <option
                value="{{ forloop.index0 }}"
                {% if variant.id == v.id %}selected{% endif %}>
                {{ variant.title | escape }}{% if variant.sku != blank %} — {{ variant.sku | escape }}{% endif %}
              </option>
            {% endfor %}
          </select>
          <div class="frq__hint" id="{{ uid }}-variant-meta">
            Geselecteerde SKU: {{ v.sku | escape }}
          </div>
        </div>

        <div>
          <label class="frq__label" for="{{ uid }}-L">Lengte (L) mm *</label>
          <input class="frq__input" id="{{ uid }}-L" name="contact[Lengte_mm]"
                 type="text" inputmode="decimal" placeholder="bijv. 500" required>
        </div>
      </div>

      <div class="frq__section-label">Gaten</div>

      <div class="frq__row frq__row--5">
        <div>
          <label class="frq__label" for="{{ uid }}-G">G links (mm)</label>
          <input class="frq__input" id="{{ uid }}-G" name="contact[G_links_mm]"
                 type="text" inputmode="decimal" placeholder="bijv. 100">
        </div>

        <div>
          <label class="frq__label" for="{{ uid }}-HH">H hart-op-hart (mm)</label>
          <input class="frq__input" id="{{ uid }}-HH" name="contact[H_hart_op_hart_mm]"
                 type="text" inputmode="decimal" placeholder="bijv. 250">
        </div>

        <div>
          <label class="frq__label" for="{{ uid }}-DIA">Gatdiameter Ø (mm)</label>
          <input class="frq__input" id="{{ uid }}-DIA" name="contact[Gatdiameter_mm]"
                 type="text" inputmode="decimal" placeholder="bijv. 30">
        </div>

        <div>
          <label class="frq__label" for="{{ uid }}-N">Aantal gaten</label>
          <input class="frq__input" id="{{ uid }}-N" name="contact[Aantal_gaten]"
                 type="number" min="0" step="1" placeholder="bijv. 2">
        </div>

        <div>
          <label class="frq__label" for="{{ uid }}-HC">HC vanaf onderzijde (mm)</label>
          <input class="frq__input" id="{{ uid }}-HC" name="contact[Hart_hoogte_gaten_mm]"
                 type="text" inputmode="decimal" placeholder="bijv. 21">
        </div>
      </div>

      <div class="frq__divider"></div>

      <div class="frq__row frq__row--3">
        <div>
          <label class="frq__label" for="{{ uid }}-name">Naam *</label>
          <input class="frq__input" id="{{ uid }}-name" name="contact[Name]"
                 type="text" required>
        </div>

        <div>
          <label class="frq__label" for="{{ uid }}-email">E-mail *</label>
          <input class="frq__input" id="{{ uid }}-email" name="contact[email]"
                 type="email" required>
        </div>

        <div>
          <label class="frq__label" for="{{ uid }}-phone">Telefoon</label>
          <input class="frq__input" id="{{ uid }}-phone" name="contact[Phone]"
                 type="tel">
        </div>
      </div>

      <div class="frq__row frq__row--2">
        <div>
          <label class="frq__label" for="{{ uid }}-qty">Aantal stuks</label>
          <input class="frq__input" id="{{ uid }}-qty" name="contact[Quantity]"
                 type="number" min="1" step="1">
        </div>

        <div>
          <label class="frq__label" for="{{ uid }}-notes">Opmerkingen</label>
          <textarea class="frq__textarea" id="{{ uid }}-notes"
                    name="contact[Notes]" rows="3"></textarea>
        </div>
      </div>

      <button class="frq__btn" type="submit">Versturen</button>
    </form>
  </div>
</div>

<style>
  #{{ uid }}{
    width: 100%;
    max-width: none;
    margin: 0 auto;
    color: #2b2b2b;
  }

  #{{ uid }} .frq__preview{
    margin-bottom: 24px;
  }

  #{{ uid }} .frq__card{
    border: 1px solid rgba(0,0,0,.10);
    border-radius: 14px;
