  #{{ uid }} .frq__svg{
    width: 100%;
    height: auto;
    display: block;
    background: #fff;
  }

  #{{ uid }} .frq__svgWarn{
    min-height: 16px;
    margin-top: 8px;
    font-size: 13px;
    color: rgba(180,0,0,.78);
  }

  #{{ uid }} .f-fill{
