<script>
(function(){
  var root = document.getElementById({{ uid | json }});
  if(!root || root.__frqInit) return;
  root.__frqInit = true;

  function $(sel){ return root.querySelector(sel); }
  function setA(el, attr, val){ if(el) el.setAttribute(attr, String(val)); }

  function num(v){
    if(v == null) return null;
    var s = String(v).trim().replace(',','.');
    var m = s.match(/(\d+(\.\d+)?)/);
    return m ? Number(m[1]) : null;
  }

  function fmt(n){
    if(n == null || isNaN(n)) return '';
    return String(Math.round(n * 10) / 10).replace('.',',');
  }

  function px(n){
    return Math.round(n * 10) / 10;
  }

  function parseProfileFromTitle(title){
    if(!title) return null;
    var s = String(title).trim();
    var m = s.match(/(\d+(?:[.,]\d+)?)\s*x\s*(\d+(?:[.,]\d+)?)\s*mm.*?d-bore\s*(\d+(?:[.,]\d+)?)\s*x\s*(\d+(?:[.,]\d+)?)\s*mm/i);

    if(!m) return null;

    return {
      A: num(m[1]),
      B: num(m[2]),
      C: num(m[3]),
      D: num(m[4])
    };
  }

  function qs(k){
    try{
      var p = new URLSearchParams(location.search || '');
      return p.get(k) || '';
    }catch(e){
      return '';
    }
  }

  function persist(k){
    var v = qs(k);
    if(v){
      try{ localStorage.setItem('frq_'+k, v); }catch(e){}
      return v;
    }
    try{ return localStorage.getItem('frq_'+k) || ''; }catch(e){ return ''; }
  }

  var variantSelectEl = $('#{{ uid }}-variant-select');
  var variantMetaEl   = $('#{{ uid }}-variant-meta');
  var variantHiddenEl = $('#{{ uid }}-variant-hidden');
  var skuHiddenEl     = $('#{{ uid }}-sku-hidden');
  var variantDataEl   = $('#{{ uid }}-variant-data');

  var lenEl   = $('#{{ uid }}-L');
  var gEl     = $('#{{ uid }}-G');
  var hhEl    = $('#{{ uid }}-HH');
  var diaEl   = $('#{{ uid }}-DIA');
  var nEl     = $('#{{ uid }}-N');
  var hcEl    = $('#{{ uid }}-HC');

  var qtyEl   = $('#{{ uid }}-qty');
  var nameEl  = $('#{{ uid }}-name');
  var emailEl = $('#{{ uid }}-email');

  var hbHiddenEl = $('#{{ uid }}-HB-hidden');
  var bHiddenEl  = $('#{{ uid }}-B-hidden');
  var cHiddenEl  = $('#{{ uid }}-C-hidden');
  var dHiddenEl  = $('#{{ uid }}-D-hidden');
  var grHiddenEl = $('#{{ uid }}-GR-hidden');

  var summEl      = $('#{{ uid }}-summary');
  var configUrlEl = $('#{{ uid }}-config-url');
  var subEl       = $('[data-sub]');
  var sucEl       = $('[data-success]');
  var svgWarn     = $('#{{ uid }}-svgwarn');

  var variants = [];
  var selectedVariant = null;
  var selectedProfile = null;
  var lastGR = null;

  try{
    variants = JSON.parse((variantDataEl && variantDataEl.textContent) || '[]');
  }catch(e){
    variants = [];
  }

  var svg      = root.querySelector('.frq__svg');
  var fFill    = svg.querySelector('.f-fill');
  var fOutline = svg.querySelector('.f-outline');
  var fHolesG  = svg.querySelector('.f-holes');
  var fWarnTxt = svg.querySelector('.f-warn');

  var DIM = {};
  svg.querySelectorAll('[data-d]').forEach(function(el){
    DIM[el.getAttribute('data-d')] = el;
  });

  function getVariantIndexById(id){
    if(!id) return -1;
    id = String(id);
    for(var i = 0; i < variants.length; i++){
      if(String(variants[i].id) === id) return i;
    }
    return -1;
  }

  function getVariantIndexBySku(sku){
    if(!sku) return -1;
    sku = String(sku).toLowerCase();
    for(var i = 0; i < variants.length; i++){
      if(String(variants[i].sku || '').toLowerCase() === sku) return i;
    }
    return -1;
  }

  function getCurrentVariant(){
    var idx = variantSelectEl ? Number(variantSelectEl.value) : 0;
    if(isNaN(idx) || idx < 0 || idx >= variants.length) idx = 0;
    return variants[idx] || null;
  }

  function applyVariantByIndex(index){
    if(!variants.length) return;

    index = Number(index);
    if(isNaN(index) || index < 0 || index >= variants.length) index = 0;

    if(variantSelectEl) variantSelectEl.value = String(index);

    selectedVariant = variants[index];
    selectedProfile = parseProfileFromTitle(selectedVariant.title);

    if(variantHiddenEl) variantHiddenEl.value = selectedVariant.title || '';
    if(skuHiddenEl) skuHiddenEl.value = selectedVariant.sku || '';

    if(variantMetaEl){
      var txt = selectedVariant.sku ? 'Geselecteerde SKU: ' + selectedVariant.sku : 'Geen SKU ingesteld';
      if(selectedProfile && selectedProfile.A){
        txt += ' · profielhoogte: ' + fmt(selectedProfile.A) + ' mm';
      }
      variantMetaEl.textContent = txt;
    }

    updateHiddenProfileFields();
    render();
  }

  function updateHiddenProfileFields(){
    if(hbHiddenEl) hbHiddenEl.value = selectedProfile && selectedProfile.A ? selectedProfile.A : '';
    if(bHiddenEl)  bHiddenEl.value  = selectedProfile && selectedProfile.B ? selectedProfile.B : '';
    if(cHiddenEl)  cHiddenEl.value  = selectedProfile && selectedProfile.C ? selectedProfile.C : '';
    if(dHiddenEl)  dHiddenEl.value  = selectedProfile && selectedProfile.D ? selectedProfile.D : '';
    if(grHiddenEl) grHiddenEl.value = lastGR != null ? fmt(lastGR) : '';
  }

  function fillTracking(){
    var byId = function(id){ return root.querySelector('#'+id); };
    var el;

    el = byId('{{ uid }}-trk-land'); if(el) el.value = location.href;
    el = byId('{{ uid }}-trk-ref');  if(el) el.value = document.referrer || '';
    el = byId('{{ uid }}-trk-ua');   if(el) el.value = navigator.userAgent || '';

    var map = {
      'utm_source':'{{ uid }}-trk-src',
      'utm_medium':'{{ uid }}-trk-med',
      'utm_campaign':'{{ uid }}-trk-camp',
      'utm_content':'{{ uid }}-trk-cont',
      'utm_term':'{{ uid }}-trk-term',
      'gclid':'{{ uid }}-trk-gclid'
    };

    for(var k in map){
      el = byId(map[k]);
      if(el) el.value = persist(k);
    }
  }

  fillTracking();

  function checkPosted(){
    if(!sucEl) return;

    try{
      var p = new URLSearchParams(location.search || '');
      if(p.get('contact_posted') === 'true'){
        sucEl.hidden = false;
        sucEl.textContent = 'Bedankt voor je aanvraag. Je ontvangt de prijs zo snel mogelijk per e-mail.';
      }
    }catch(e){}
  }

  checkPosted();

  function buildConfigUrl(){
    var url = new URL(location.href);
    var p = url.searchParams;

    if(selectedVariant && selectedVariant.id) p.set('frq_variant', selectedVariant.id);
    if(selectedVariant && selectedVariant.sku) p.set('frq_sku', selectedVariant.sku);

    var fields = {
      frq_L: lenEl && lenEl.value,
      frq_G: gEl && gEl.value,
      frq_H: hhEl && hhEl.value,
      frq_DIA: diaEl && diaEl.value,
      frq_N: nEl && nEl.value,
      frq_HC: hcEl && hcEl.value,
      frq_QTY: qtyEl && qtyEl.value
    };

    Object.keys(fields).forEach(function(k){
      var v = String(fields[k] || '').trim();
      if(v) p.set(k, v);
      else p.delete(k);
    });

    p.delete('contact_posted');

    return url.toString();
  }

  function updateSub(){
    if(!subEl) return;

    var L = num(lenEl && lenEl.value);
    var HB = selectedProfile && selectedProfile.A;
    var hasBlock = L > 0 && HB > 0;
    var n = String((nameEl && nameEl.value) || '').trim();
    var e = String((emailEl && emailEl.value) || '').trim();
    var hasContact = n.length > 0 && e.indexOf('@') > 0;

    if(!selectedVariant){
      subEl.textContent = 'Kies eerst een variant.';
    } else if(!hasBlock){
      subEl.textContent = 'Vul de lengte in om het zijaanzicht te tekenen.';
    } else if(!hasContact){
      subEl.textContent = 'Vul je contactgegevens in om de aanvraag te versturen.';
    } else {
      subEl.textContent = 'Verstuur je aanvraag. Wij ontvangen de maten en configuratie-URL per e-mail.';
    }
  }

  function updateSummary(){
    if(!summEl) return;

    var configUrl = buildConfigUrl();
    if(configUrlEl) configUrlEl.value = configUrl;

    summEl.value =
      'Profiel=' + ((selectedVariant && selectedVariant.title) || '') + '; ' +
      'SKU=' + ((selectedVariant && selectedVariant.sku) || '') + '; ' +
      'Profielhoogte HB=' + ((selectedProfile && selectedProfile.A) || '') + 'mm; ' +
      'Profielbreedte B=' + ((selectedProfile && selectedProfile.B) || '') + 'mm; ' +
      'Kamerhoogte C=' + ((selectedProfile && selectedProfile.C) || '') + 'mm; ' +
      'Kamerbreedte D=' + ((selectedProfile && selectedProfile.D) || '') + 'mm; ' +
      'L=' + (num(lenEl && lenEl.value) || '') + 'mm; ' +
      'G links=' + (num(gEl && gEl.value) || '') + 'mm; ' +
      'H=' + (num(hhEl && hhEl.value) || '') + 'mm; ' +
      'GR rechts=' + (lastGR != null ? fmt(lastGR) : '') + 'mm; ' +
      'Ø=' + (num(diaEl && diaEl.value) || '') + 'mm; ' +
      'N=' + (num(nEl && nEl.value) || '') + '; ' +
      'HC=' + (num(hcEl && hcEl.value) || '') + 'mm; ' +
      'Configuratie URL=' + configUrl;
  }

  function dimOff(key){
    var el = DIM[key];
    if(!el) return;

    el.style.display = 'none';

    if(el.tagName && el.tagName.toLowerCase() === 'text'){
      el.textContent = '';
    } else {
      setA(el,'x1',0);
      setA(el,'y1',0);
      setA(el,'x2',0);
      setA(el,'y2',0);
    }
  }

  function resetAll(){
    setA(fFill,'x',0);
    setA(fFill,'y',0);
    setA(fFill,'width',0);
    setA(fFill,'height',0);

    setA(fOutline,'x',0);
    setA(fOutline,'y',0);
    setA(fOutline,'width',0);
    setA(fOutline,'height',0);

    fHolesG.innerHTML = '';

    if(fWarnTxt) fWarnTxt.textContent = '';
    if(svgWarn) svgWarn.textContent = '';

    [
      'L-el','L-er','L-line','L-text',
      'HB-et','HB-eb','HB-line','HB-text',
      'G-el','G-em','G-line','G-text',
      'H-em','H-er','H-line','H-text',
      'GR-el','GR-er','GR-line','GR-text',
      'DIA-text',
      'C-top','C-bot',
      'HC-et','HC-eb','HC-line','HC-text'
    ].forEach(dimOff);
  }

  function dimLine(keyEl, keyEr, keyLine, keyText, x1, y1, x2, y2, yDim, label, anchor){
    var el = DIM[keyEl];
    if(el){
      setA(el,'x1',px(x1));
      setA(el,'y1',px(y1));
      setA(el,'x2',px(x1));
      setA(el,'y2',px(yDim));
      el.style.display='';
    }

    var er = DIM[keyEr];
    if(er){
      setA(er,'x1',px(x2));
      setA(er,'y1',px(y2));
      setA(er,'x2',px(x2));
      setA(er,'y2',px(yDim));
      er.style.display='';
    }

    var ln = DIM[keyLine];
    if(ln){
      setA(ln,'x1',px(x1));
      setA(ln,'y1',px(yDim));
      setA(ln,'x2',px(x2));
      setA(ln,'y2',px(yDim));
      ln.style.display='';
    }

    var tx = DIM[keyText];
    if(tx){
      tx.textContent = label;
      setA(tx,'x', px((x1+x2)/2));
      setA(tx,'y', px(yDim - 7));
      if(anchor) setA(tx,'text-anchor', anchor);
      tx.style.display='';
    }
  }

  function render(){
    resetAll();

    var L   = num(lenEl && lenEl.value);
    var HB  = selectedProfile && selectedProfile.A ? selectedProfile.A : null;
    var chamberC = selectedProfile && selectedProfile.C ? selectedProfile.C : null;

    var G   = num(gEl && gEl.value);
    var HH  = num(hhEl && hhEl.value);
    var DIA = num(diaEl && diaEl.value);
    var N   = num(nEl && nEl.value);
    var HC  = num(hcEl && hcEl.value);

    lastGR = null;

    if(N != null) N = Math.max(0, Math.round(N));

    updateSub();

    if(!(L > 0) || !(HB > 0)){
      updateHiddenProfileFields();
      updateSummary();
      return;
    }

    var SVG_W = 1200;
    var SVG_H = 430;

    var PAD_L = 95;
    var PAD_R = 190;
    var PAD_T = 70;
    var PAD_B = 105;

    var maxFW = SVG_W - PAD_L - PAD_R;
    var maxFH = SVG_H - PAD_T - PAD_B;

    var scale = Math.min(maxFW / L, maxFH / HB);
    var fW = L * scale;
    var fH = HB * scale;

    var clamped = false;

    if(fW < 50){
      fW = 50;
      clamped = true;
    }

    if(fH < 28){
      fH = 28;
      clamped = true;
    }

    var fx = PAD_L + (maxFW - fW) / 2;
    var fy = PAD_T + (maxFH - fH) / 2;

    setA(fFill,'x',fx);
    setA(fFill,'y',fy);
    setA(fFill,'width',fW);
    setA(fFill,'height',fH);

    setA(fOutline,'x',fx);
    setA(fOutline,'y',fy);
    setA(fOutline,'width',fW);
    setA(fOutline,'height',fH);

    /*
      Kamer/stippellijnen:
      Geen label, geen C-maatlijn.
      Alleen 2 horizontale stippellijnen over volledige breedte.
    */
    if(chamberC > 0 && chamberC < HB){
      var cH = chamberC * scale;
      var yC1 = fy + (fH - cH) / 2;
      var yC2 = yC1 + cH;

      var cTop = DIM['C-top'];
      var cBot = DIM['C-bot'];

      if(cTop){
        setA(cTop, 'x1', px(fx));
        setA(cTop, 'y1', px(yC1));
        setA(cTop, 'x2', px(fx + fW));
        setA(cTop, 'y2', px(yC1));
        cTop.style.display = '';
      }

      if(cBot){
        setA(cBot, 'x1', px(fx));
        setA(cBot, 'y1', px(yC2));
        setA(cBot, 'x2', px(fx + fW));
        setA(cBot, 'y2', px(yC2));
        cBot.style.display = '';
      }
    }

    var hasHoles = G > 0 && DIA > 0 && N > 0;
    var holeFitWarn = false;
    var firstHoleX = null;
    var holeCy = null;

    if(hasHoles){
      var NS = 'http://www.w3.org/2000/svg';
      var rH = (DIA / 2) * scale;

      if(HC > 0){
        holeCy = fy + fH - (HC * scale);
      } else {
        holeCy = fy + fH / 2;
      }

      for(var i = 0; i < N; i++){
        var cx_h;

        if(i === 0){
          cx_h = fx + G * scale;
        } else {
          if(!(HH > 0)) break;
          cx_h = fx + G * scale + i * HH * scale;
        }

        if(i === 0) firstHoleX = cx_h;

        var margin = 2;

        if(cx_h - rH < fx + margin ||
           cx_h + rH > fx + fW - margin ||
           holeCy - rH < fy + margin ||
           holeCy + rH > fy + fH - margin){
          holeFitWarn = true;
          continue;
        }

        var c = document.createElementNS(NS,'circle');
        c.setAttribute('cx', cx_h);
        c.setAttribute('cy', holeCy);
        c.setAttribute('r', rH);
        fHolesG.appendChild(c);

        var ext = Math.max(rH * 1.4, rH + 6);

        var lh = document.createElementNS(NS,'line');
        lh.setAttribute('class','f-cross');
        lh.setAttribute('x1', cx_h - ext);
        lh.setAttribute('x2', cx_h + ext);
        lh.setAttribute('y1', holeCy);
        lh.setAttribute('y2', holeCy);
        fHolesG.appendChild(lh);

        var lv = document.createElementNS(NS,'line');
        lv.setAttribute('class','f-cross');
        lv.setAttribute('x1', cx_h);
        lv.setAttribute('x2', cx_h);
        lv.setAttribute('y1', holeCy - ext);
        lv.setAttribute('y2', holeCy + ext);
        fHolesG.appendChild(lv);
      }

      if(holeFitWarn && svgWarn){
        svgWarn.textContent = 'Gaten passen niet binnen het blok — controleer G, H, Ø, HC en lengte.';
      }
    }

    if(clamped && fWarnTxt){
      fWarnTxt.textContent = 'NIET OP SCHAAL';
    }

    var yDimL = fy - 30;

    dimLine(
      'L-el','L-er','L-line','L-text',
      fx, fy, fx + fW, fy, yDimL,
      'L = ' + fmt(L) + ' mm',
      'middle'
    );

    /*
      Profielhoogte links.
      Niet invulbaar, maar wel zichtbaar omdat dit technisch relevant blijft.
    */
    var xDimH = fx - 52;

    var etEl = DIM['HB-et'];
    var ebEl = DIM['HB-eb'];
    var lineEl = DIM['HB-line'];
    var textEl = DIM['HB-text'];

    if(etEl){
      setA(etEl,'x1',px(xDimH));
      setA(etEl,'y1',px(fy));
      setA(etEl,'x2',px(fx));
      setA(etEl,'y2',px(fy));
      etEl.style.display='';
    }

    if(ebEl){
      setA(ebEl,'x1',px(xDimH));
      setA(ebEl,'y1',px(fy+fH));
      setA(ebEl,'x2',px(fx));
      setA(ebEl,'y2',px(fy+fH));
      ebEl.style.display='';
    }

    if(lineEl){
      setA(lineEl,'x1',px(xDimH));
      setA(lineEl,'y1',px(fy));
      setA(lineEl,'x2',px(xDimH));
      setA(lineEl,'y2',px(fy+fH));
      lineEl.style.display='';
    }

    if(textEl){
      var midY = fy + fH / 2;
      textEl.removeAttribute('transform');
      textEl.setAttribute('transform', 'rotate(-90,' + px(xDimH - 10) + ',' + px(midY) + ')');
      setA(textEl,'x', px(xDimH - 10));
      setA(textEl,'y', px(midY + 4));
      setA(textEl,'text-anchor','middle');
      textEl.textContent = 'HB = ' + fmt(HB) + ' mm';
      textEl.style.display = '';
    }

    if(hasHoles && G > 0){
      var yDimGH = fy + fH + 42;
      var yDimGR = yDimGH + 28;
      var yExtStart = fy + fH;

      var fxG0 = fx;
      var fxG1 = fx + G * scale;

      var gElDim   = DIM['G-el'];
      var gEmDim   = DIM['G-em'];
      var gLineDim = DIM['G-line'];
      var gTextDim = DIM['G-text'];

      if(gElDim){
        setA(gElDim,'x1',px(fxG0));
        setA(gElDim,'y1',px(yExtStart));
        setA(gElDim,'x2',px(fxG0));
        setA(gElDim,'y2',px(yDimGH));
        gElDim.style.display='';
      }

      if(gEmDim){
        setA(gEmDim,'x1',px(fxG1));
        setA(gEmDim,'y1',px(yExtStart));
        setA(gEmDim,'x2',px(fxG1));
        setA(gEmDim,'y2',px(yDimGH));
        gEmDim.style.display='';
      }

      if(gLineDim){
        setA(gLineDim,'x1',px(fxG0));
        setA(gLineDim,'y1',px(yDimGH));
        setA(gLineDim,'x2',px(fxG1));
        setA(gLineDim,'y2',px(yDimGH));
        gLineDim.style.display='';
      }

      if(gTextDim){
        gTextDim.textContent = 'G = ' + fmt(G) + ' mm';
        setA(gTextDim,'x',px((fxG0+fxG1)/2));
        setA(gTextDim,'y',px(yDimGH+14));
        gTextDim.style.display='';
      }

      if(N > 1 && HH > 0){
        var fxH1 = fxG1;
        var fxH2 = fxG1 + HH * scale;

        var hErDim   = DIM['H-er'];
        var hLineDim = DIM['H-line'];
        var hTextDim = DIM['H-text'];

        if(hErDim){
          setA(hErDim,'x1',px(fxH2));
          setA(hErDim,'y1',px(yExtStart));
          setA(hErDim,'x2',px(fxH2));
          setA(hErDim,'y2',px(yDimGH));
          hErDim.style.display='';
        }

        if(hLineDim){
          setA(hLineDim,'x1',px(fxH1));
          setA(hLineDim,'y1',px(yDimGH));
          setA(hLineDim,'x2',px(fxH2));
          setA(hLineDim,'y2',px(yDimGH));
          hLineDim.style.display='';
        }

        if(hTextDim){
          hTextDim.textContent = 'H = ' + fmt(HH) + ' mm';
          setA(hTextDim,'x',px((fxH1+fxH2)/2));
          setA(hTextDim,'y',px(yDimGH+14));
          hTextDim.style.display='';
        }
      }

      var lastHoleDistance = G;

      if(N > 1 && HH > 0){
        lastHoleDistance = G + ((N - 1) * HH);
      }

      var GR = L - lastHoleDistance;
      lastGR = GR > 0 ? GR : null;

      if(GR > 0 && lastHoleDistance > 0){
        var fxGR1 = fx + lastHoleDistance * scale;
        var fxGR2 = fx + fW;

        var grElDim   = DIM['GR-el'];
        var grErDim   = DIM['GR-er'];
        var grLineDim = DIM['GR-line'];
        var grTextDim = DIM['GR-text'];

        if(grElDim){
          setA(grElDim,'x1',px(fxGR1));
          setA(grElDim,'y1',px(yExtStart));
          setA(grElDim,'x2',px(fxGR1));
          setA(grElDim,'y2',px(yDimGR));
          grElDim.style.display='';
        }

        if(grErDim){
          setA(grErDim,'x1',px(fxGR2));
          setA(grErDim,'y1',px(yExtStart));
          setA(grErDim,'x2',px(fxGR2));
          setA(grErDim,'y2',px(yDimGR));
          grErDim.style.display='';
        }

        if(grLineDim){
          setA(grLineDim,'x1',px(fxGR1));
          setA(grLineDim,'y1',px(yDimGR));
          setA(grLineDim,'x2',px(fxGR2));
          setA(grLineDim,'y2',px(yDimGR));
          grLineDim.style.display='';
        }

        if(grTextDim){
          grTextDim.textContent = 'GR = ' + fmt(GR) + ' mm';
          setA(grTextDim,'x',px((fxGR1 + fxGR2) / 2));
          setA(grTextDim,'y',px(yDimGR + 14));
          grTextDim.style.display='';
        }
      } else if(svgWarn && lastHoleDistance > L){
        svgWarn.textContent = 'De laatste gatpositie valt buiten de lengte — controleer G, H, N en L.';
      }

      if(DIA > 0 && firstHoleX != null && holeCy != null){
        var diaTxt = DIM['DIA-text'];

        if(diaTxt){
          var rH2 = (DIA / 2) * scale;
          diaTxt.textContent = 'Ø ' + fmt(DIA) + ' mm';
          setA(diaTxt,'x', px(firstHoleX));
          setA(diaTxt,'y', px(holeCy + rH2 + 14));
          diaTxt.style.display = '';
        }
      }
    }

    if(hasHoles && HC > 0 && holeCy != null){
      var xDimHC = fx + fW + 92;
      var yBottom = fy + fH;

      var hcEt = DIM['HC-et'];
      var hcEb = DIM['HC-eb'];
      var hcLn = DIM['HC-line'];
      var hcTx = DIM['HC-text'];

      if(hcEt){
        setA(hcEt,'x1',px(fx + fW));
        setA(hcEt,'y1',px(holeCy));
        setA(hcEt,'x2',px(xDimHC));
        setA(hcEt,'y2',px(holeCy));
        hcEt.style.display='';
      }

      if(hcEb){
        setA(hcEb,'x1',px(fx + fW));
        setA(hcEb,'y1',px(yBottom));
        setA(hcEb,'x2',px(xDimHC));
        setA(hcEb,'y2',px(yBottom));
        hcEb.style.display='';
      }

      if(hcLn){
        setA(hcLn,'x1',px(xDimHC));
        setA(hcLn,'y1',px(holeCy));
        setA(hcLn,'x2',px(xDimHC));
        setA(hcLn,'y2',px(yBottom));
        hcLn.style.display='';
      }

      if(hcTx){
        hcTx.textContent = 'HC = ' + fmt(HC) + ' mm';
        setA(hcTx,'x',px(xDimHC + 8));
        setA(hcTx,'y',px((holeCy + yBottom) / 2 + 4));
        setA(hcTx,'text-anchor','start');
        hcTx.style.display='';
      }
    }

    updateHiddenProfileFields();
    updateSummary();
  }

  function loadFromUrl(){
    var variantId = qs('frq_variant');
    var variantSku = qs('frq_sku');

    var idx = -1;

    if(variantId) idx = getVariantIndexById(variantId);
    if(idx < 0 && variantSku) idx = getVariantIndexBySku(variantSku);

    if(idx >= 0 && variantSelectEl){
      variantSelectEl.value = String(idx);
    }

    var map = {
      frq_L: lenEl,
      frq_G: gEl,
      frq_H: hhEl,
      frq_DIA: diaEl,
      frq_N: nEl,
      frq_HC: hcEl,
      frq_QTY: qtyEl
    };

    Object.keys(map).forEach(function(k){
      var el = map[k];
      var v = qs(k);
      if(el && v) el.value = v;
    });
  }

  var inputs = [
    lenEl, gEl, hhEl, diaEl, nEl, hcEl,
    qtyEl, nameEl, emailEl
  ];

  inputs.forEach(function(el){
    if(!el) return;

    el.addEventListener('input', function(){
      render();
    }, {passive:true});

    el.addEventListener('change', function(){
      render();
    }, {passive:true});
  });

  if(variantSelectEl){
    variantSelectEl.addEventListener('change', function(){
      applyVariantByIndex(this.value);
    });
  }

  loadFromUrl();

  if(variants.length){
    var initialIndex = variantSelectEl ? Number(variantSelectEl.value) : 0;
    if(isNaN(initialIndex)) initialIndex = 0;
    applyVariantByIndex(initialIndex);
  } else {
    render();
  }

})();
</script>

{%- comment -%}
  FENDER RFQ — Nederlands
  Zijaanzicht met variant-selectie en boorplan.
{%- endcomment -%}

{%- assign v   = product.selected_or_first_available_variant -%}
{%- assign uid = 'fender-rfq-' | append: product.id -%}

<div id="{{ uid }}" class="frq">
  <div class="frq__preview">
    <div class="frq__card">
      <div class="frq__head">
        <div>
          <div class="frq__headTitle">Zijaanzicht (2D)</div>
          <div class="frq__headSub">Live preview van uw configuratie</div>
        </div>
        <div class="frq__headMeta">Technische Tekening</div>
      </div>

      <div class="frq__svgWrap">
        <svg id="{{ uid }}-svg" viewBox="0 0 1200 480" preserveAspectRatio="xMidYMid meet" class="frq__svg">
          <defs>
            <marker id="{{ uid }}-arr" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse">
              <path d="M 0 0 L 10 5 L 0 10 z" fill="#64748b"/>
            </marker>
          </defs>
          <!-- Getekend door JS -->
        </svg>
      </div>
    </div>
  </div>

  <div class="frq__form">
    <h3 class="frq__title">Configureer & Vraag Offerte</h3>
    <p class="frq__sub">Kies een variant en pas de boormaten aan voor een prijs op maat.</p>

    {%- form 'contact', id: uid -%}
      {%- if form.posted_successfully? -%}
        <div class="frq__success">Bedankt! Uw aanvraag is verzonden. Wij nemen zo snel mogelijk contact met u op.</div>
      {%- endif -%}

      <input type="hidden" name="contact[Product]" value="{{ product.title | escape }}">
      <input type="hidden" name="contact[Configuratie]" id="{{ uid }}-summary">

      <div class="frq__section-label">01. Profiel</div>
      <div class="frq__row frq__row--2">
         <div>
            <label class="frq__label">Variant</label>
            <select id="{{ uid }}-v-select" class="frq__input" name="contact[Variant]">
              {% for variant in product.variants %}
                <option value="{{ variant.id }}" data-title="{{ variant.title | escape }}" {% if variant.id == v.id %}selected{% endif %}>
                  {{ variant.title | escape }}
                </option>
              {% endfor %}
              <option value="custom">Aangepast...</option>
            </select>
         </div>
         <div>
            <label class="frq__label">Lengte (L) mm</label>
            <input type="number" id="{{ uid }}-in-l" name="contact[Lengte_mm]" value="1000" class="frq__input">
         </div>
      </div>

      <div id="{{ uid }}-custom-dims" class="frq__custom-box" style="display:none;">
        <div class="frq__row frq__row--2">
          <div>
            <label class="frq__label">Hoogte (HB)</label>
            <input type="number" id="{{ uid }}-in-hb" value="42" class="frq__input">
          </div>
          <div>
            <label class="frq__label">Kamer (C)</label>
            <input type="number" id="{{ uid }}-in-c" value="27" class="frq__input">
          </div>
        </div>
      </div>

      <div class="frq__section-label">02. Boorplan</div>
      <div class="frq__row frq__row--2">
        <div>
          <label class="frq__label">Boormaat</label>
          <div class="frq__row" style="margin-bottom:0">
