<script>
(function() {
  const uid = '{{ uid }}';
  const el = (n) => document.getElementById(uid + '-' + n);
  const M_VALS = { M8: 9, M10: 11, M12: 14, M16: 18, M20: 22 };

  function parse(title) {
    const m = title.match(/(\d+)x(\d+)mm.*?bore (\d+)x(\d+)/i);
    return m ? { hb: parseInt(m[1]), c: parseInt(m[3]) } : { hb: 42, c: 27 };
  }

  function draw() {
    const vSel = el('v-select');
    const isC = vSel.value === 'custom';
    el('custom-dims').style.display = isC ? 'block' : 'none';

    let hb, c;
    if(isC) {
      hb = parseInt(el('in-hb').value) || 42;
      c = parseInt(el('in-c').value) || 27;
    } else {
      const p = parse(vSel.options[vSel.selectedIndex].getAttribute('data-title'));
      hb = p.hb; c = p.c;
    }

    const L = parseInt(el('in-l').value) || 1000;
    const G = parseInt(el('in-g').value) || 100;
    const H = parseInt(el('in-h').value) || 200;
    const N = parseInt(el('in-n').value) || 0;
    const HC = parseInt(el('in-hc').value) || 21;
    const dt = el('in-dtype').value;
    const dDia = dt === 'custom' ? (parseInt(el('in-dcustom').value) || 10) : M_VALS[dt];

    el('in-dcustom').style.display = dt === 'custom' ? 'block' : 'none';

    const VW = 1200, VH = 480, PAD = 100;
    const scale = Math.min((VW - PAD*2)/L, (VH - PAD*2 - 80)/hb);
    const fW = L * scale, fH = hb * scale;
    const sX = (VW - fW)/2, sY = (VH - fH)/2 + 20;
    const svg = el('svg');

    let hHtml = '', tHtml = '', summary = '';
    for(let i=0; i<N; i++) {
      const x = G + (i * H);
      if(x > L) break;
      const hX = sX + x * scale, hY = sY + (hb - HC) * scale, r = (dDia/2) * scale;

      hHtml += `
        <line x1="${hX}" y1="${sY-45}" x2="${hX}" y2="${sY+fH+85}" stroke="#3b82f6" stroke-width="1.5" stroke-dasharray="6,4" opacity="0.4" />
        <g>
          <rect x="${hX-35}" y="${sY-40}" width="70" height="24" rx="12" fill="#eff6ff" stroke="#3b82f6" stroke-width="1" />
          <text x="${hX}" y="${sY-23}" text-anchor="middle" font-family="monospace" font-size="15" font-weight="900" fill="#1d4ed8">${x}</text>
        </g>
        <circle cx="${hX}" cy="${hY}" r="${r}" fill="#fff" stroke="#0f172a" stroke-width="2.5" />
        <line x1="${hX-r-6}" y1="${hY}" x2="${hX+r+6}" y2="${hY}" stroke="#0f172a" stroke-width="0.8" />
        <line x1="${hX}" y1="${hY-r-6}" x2="${hX}" y2="${hY+r+6}" stroke="#0f172a" stroke-width="0.8" />
      `;
      tHtml += `<tr><td>#${i+1}</td><td style="font-weight:700">${x} mm</td><td>${HC} mm</td><td>${dt==='custom'?'Ø'+dDia:dt}</td></tr>`;
      summary += `Gat ${i+1}: X=${x}mm, HC=${HC}mm; `;
    }

    if(N==0) tHtml = '<tr><td colspan="4" style="text-align:center; padding:30px; color:#94a3b8">Geen gaten geconfigureerd</td></tr>';

    svg.innerHTML = `
      <defs><marker id="{{ uid }}-arr" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#64748b" /></marker></defs>
      <rect x="${sX}" y="${sY}" width="${fW}" height="${fH}" fill="#fff" stroke="#0f172a" stroke-width="3" rx="4" />
      <line x1="${sX}" y1="${sY + (fH - c*scale)/2}" x2="${sX+fW}" y2="${sY + (fH - c*scale)/2}" stroke="#94a3b8" stroke-width="1" stroke-dasharray="8,6" opacity="0.6" />
      <line x1="${sX}" y1="${sY + (fH + c*scale)/2}" x2="${sX+fW}" y2="${sY + (fH + c*scale)/2}" stroke="#94a3b8" stroke-width="1" stroke-dasharray="8,6" opacity="0.6" />
      <g>
        <line x1="${sX}" y1="${sY-70}" x2="${sX+fW}" y2="${sY-70}" stroke="#64748b" stroke-width="2" marker-start="url(#{{ uid }}-arr)" marker-end="url(#{{ uid }}-arr)" />
        <text x="${sX+fW/2}" y="${sY-82}" text-anchor="middle" font-size="24" font-weight="900">L = ${L}mm</text>
      </g>
      <g>
        <line x1="${sX-60}" y1="${sY}" x2="${sX-60}" y2="${sY+fH}" stroke="#64748b" stroke-width="2" marker-start="url(#{{ uid }}-arr)" marker-end="url(#{{ uid }}-arr)" />
        <text x="${sX-80}" y="${sY+fH/2}" text-anchor="middle" transform="rotate(-90,${sX-80},${sY+fH/2})" font-size="22" font-weight="900">HB = ${hb}mm</text>
      </g>
      ${hHtml}
      ${N>0 ? `
        <g>
          <line x1="${sX+fW+50}" y1="${sY+fH}" x2="${sX+fW+50}" y2="${hY}" stroke="#64748b" stroke-width="1.5" marker-start="url(#{{ uid }}-arr)" marker-end="url(#{{ uid }}-arr)" />
          <text x="${sX+fW+65}" y="${hY+5}" text-anchor="start" font-size="16" font-weight="900">HC = ${HC}mm</text>
        </g>
      ` : ''}
    `;
    el('table-body').innerHTML = tHtml;
    el('summary').value = `Lengte: ${L}mm, HB: ${hb}mm, C: ${c}mm, Boor: ${dt==='custom'?dDia:dt}, ` + summary;
  }

  ['v-select', 'in-l', 'in-g', 'in-h', 'in-n', 'in-hc', 'in-dtype', 'in-dcustom', 'in-hb', 'in-c'].forEach(i => el(i).addEventListener('input', draw));
  draw();
})();
</script>

